/**
 * Indexes an issue only while the issue and its project are both live.
 * Otherwise the issue document is removed.
 */
export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  if (!isLive(issue) || !(await projectIsLive(orgId, issue.projectId))) {
    await removeFromIndex(orgId, "issue", issue.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\n"),
    issue.projectId,
  );
}

/**
 * Indexes a comment only while the comment, its issue and that issue's
 * project are all live. Otherwise the comment document is removed.
 */
export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  if (!isLive(comment)) {
    await removeFromIndex(orgId, "comment", comment.id);
    return;
  }

  const issue = await issueRepo.findIssueById(orgId, comment.issueId);
  if (!issue || !isLive(issue) || !(await projectIsLive(orgId, issue.projectId))) {
    await removeFromIndex(orgId, "comment", comment.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    issue.projectId,
  );
}

/** Indexes a project only while it is live. Otherwise the document is removed. */
export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  if (!isLive(project)) {
    await removeFromIndex(orgId, "project", project.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\n"),
    project.id,
  );
}

