import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as searchRepo from "@/server/repositories/search-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { SearchSubjectKind } from "@/server/repositories/search-repository";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

async function find(
  actor: Actor,
  orgId: OrgId,
  q: string,
  kinds: readonly SearchSubjectKind[],
  limit = 25,
) {
  return searchService.search(actor, {
    orgId,
    q,
    kinds: [...kinds],
    limit,
    cursor: null,
  });
}

describe("search visibility", () => {
  it("hides an archived issue and every comment on it", async () => {
    const tenant = await createTenant("archissue", "growth");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "ArchIssueMarker" }),
    );
    const sibling = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "SiblingStaysMarker" }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "ArchCommentOne",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "ArchCommentTwo",
      parentId: null,
      mentionedUserIds: [],
    });

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    const issues = await find(tenant.actors.member, tenant.org.id, "ArchIssueMarker", ["issue"]);
    const comments = await find(tenant.actors.member, tenant.org.id, "ArchComment", ["comment"]);
    const siblingHits = await find(tenant.actors.member, tenant.org.id, "SiblingStaysMarker", ["issue"]);

    expect(issues.total).toBe(0);
    expect(issues.items).toHaveLength(0);
    expect(comments.total).toBe(0);
    expect(siblingHits.total).toBe(1);
    expect(siblingHits.items[0]?.id).toBe(sibling.id);
  });

  it("hides a project's issues and comments, including later writes, until restore", async () => {
    const tenant = await createTenant("archproj", "growth");
    const project = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Kept Project Marker",
      slug: "kept-project",
      key: "KPT",
      description: "KeptProjectBody",
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const side = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Side Project Marker",
      slug: "side-project",
      key: "SID",
      description: "SideProjectBody",
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const kept = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, project.id, { title: "KeptIssueMarker" }),
    );
    const alreadyArchived = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, project.id, { title: "PreArchivedIssueMarker" }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: kept.id,
      body: "KeptCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: alreadyArchived.id,
      body: "PreArchivedCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    const sideIssue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, side.id, { title: "SideIssueMarker" }),
    );
    await issueService.archiveIssue(
      tenant.actors.member,
      tenant.org.id,
      alreadyArchived.id,
    );

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: false,
    });

    expect((await find(tenant.actors.member, tenant.org.id, "Kept Project Marker", ["project"])).total).toBe(0);
    expect((await find(tenant.actors.member, tenant.org.id, "KeptIssueMarker", ["issue"])).total).toBe(0);
    expect((await find(tenant.actors.member, tenant.org.id, "KeptCommentMarker", ["comment"])).total).toBe(0);
    expect((await find(tenant.actors.member, tenant.org.id, "PreArchivedIssueMarker", ["issue"])).total).toBe(0);
    expect((await find(tenant.actors.member, tenant.org.id, "SideIssueMarker", ["issue"])).total).toBe(1);
    expect((await find(tenant.actors.member, tenant.org.id, "Side Project Marker", ["project"])).total).toBe(1);

    await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: kept.id,
      title: "KeptIssueEditedMarker",
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: kept.id,
      body: "CommentWhileArchivedMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    const posted = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: sideIssue.id,
      body: "EditableCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: posted.id,
