    const archivedHit = await find(tenant.actors.member, tenant.org.id, "ArchivedBulkIssue", ["issue"]);
    const archivedComment = await find(tenant.actors.member, tenant.org.id, "ArchivedBulkComment", ["comment"]);
    const deleted = await find(tenant.actors.member, tenant.org.id, "DeletedCommentMarker", ["comment"]);
    const orphan = await find(tenant.actors.member, tenant.org.id, "OrphanMarkerUnique", ["issue"]);
