    expect(lastBulkComment.total).toBe(1);
    expect(bulkIssues.total).toBe(100);
    expect(bulkIssues.items).toHaveLength(100);
    expect(renamed.total).toBe(1);
    expect(archivedHit.total).toBe(0);
    expect(archivedComment.total).toBe(0);
    expect(deleted.total).toBe(0);
    expect(orphan.total).toBe(0);
    expect(otherHit.total).toBe(1);
    expect(otherHit.items[0]?.id).toBe(otherIssue.id);
    expect(otherOrphan.total).toBe(1);
    expect(await searchRepo.countIndexed(other.org.id)).toBe(otherIndexed);
  }, 60_000);
